class DynamicResource {
    int* ptr;
public:
    // Ctor: Resource Acquisition
    explicit DynamicResource(size_t s)
        : ptr(new int[s]) {}

    // Dtor: Resource Release (Guaranteed execution)
    ~DynamicResource() {
        delete[] ptr;
    }

    // Modern C++ standard practice: Disable Copy/Assignment
    DynamicResource(const DynamicResource&) = delete;
    DynamicResource& operator=(const DynamicResource&) = delete;
};

// Usage: Object lifetime determines resource lifetime
void function_scope() {
    DynamicResource r(50); // Resource acquired
    // ... use r
    // r destroyed, destructor called, resource freed.
}
